package br.com.omnilog.payments; import java.math.BigDecimal; public final class BoletoBancario implements ProcessadorPagamento { public ResultadoPagamento processar(BigDecimal v,String r){validar(v,r);return new ResultadoPagamento(false,"BOLETO",r,"Boleto simulado; aguardando compensação");} static void validar(BigDecimal v,String r){if(v==null||v.signum()<=0||r==null||r.isBlank())throw new IllegalArgumentException("Valor e referência obrigatórios");} }
